<body>
<div class="container">
<header>
<h1>预约清洁</h1>
</header>
<nav>
<a href="index.html">主页</a>
<a href="about.html">关于我们</a>
<a href="services.html">服务</a>
<a href="booking.html">预约清洁</a>
</nav>
<section class="hero">
<h1>预约清洁服务</h1>
</section>
<section>
<h2>预约表单</h2>
<form id="bookingForm" novalidate>
<div>
<label for="name">姓名</label>
<input type="text" id="name" name="name" required>
<div class="error" id="nameError"></div>
</div>
<div>
<label for="phone">手机号码</label>
<input type="tel" id="phone" name="phone" required pattern="[0-9]{11}">
<div class="error" id="phoneError"></div>
</div>
<div>
<label for="email">电子邮件</label>
<input type="email" id="email" name="email" required>
<div class="error" id="emailError"></div>
</div>
<div>
<label for="service">服务类型</label>
<select id="service" name="service" required>
<option value="">请选择</option>
<option value="常规清洁">常规清洁</option>
<option value="深度清洁">深度清洁</option>
<option value="入住/退房清洁">入住/退房清洁</option>
<option value="窗玻璃清洁">窗玻璃清洁</option>
<option value="绿植养护">绿植养护</option>
</select>
<div class="error" id="serviceError"></div>
</div>
<div>
<label for="date">日期</label>
<input type="date" id="date" name="date" required>
<div class="error" id="dateError"></div>
</div>
<div>
<label for="time">时间段</label>
<select id="time" name="time" required>
<option value="">请选择</option>
<option value="上午">上午 (9:00-12:00)</option>
<option value="下午">下午 (13:00-16:00)</option>
</select>
<div class="error" id="timeError"></div>
</div>
<div>
<label for="notes">备注</label>
<textarea id="notes" name="notes" rows="3"></textarea>
</div>
<button type="submit">提交预约</button>
</form>
</section>
<footer>
<p>联系电话：<a href="tel:+861012345678">010-12345678</a></p>
<p>邮箱：<a href="mailto:service@jiajia.com">洁家家政邮箱</a></p>
<p><a href="index.html">主页</a> | <a href="about.html">关于我们</a> | <a href="services.html">服务项目</a> | <a href="booking.html">预约清洁</a></p>
</footer>

<script>
document.getElementById('bookingForm').addEventListener('submit', function(e){
e.preventDefault();
var name = document.getElementById('name').value.trim();
var phone = document.getElementById('phone').value.trim();
var email = document.getElementById('email').value.trim();
var service = document.getElementById('service').value;
var date = document.getElementById('date').value;
var time = document.getElementById('time').value;
var errors = [];

if(name === ''){ errors.push('请填写姓名'); }
if(phone === '' || !/^[0-9]{11}$/.test(phone)){ errors.push('请填写有效的11位手机号'); }
if(email === ''){ errors.push('请填写电子邮件'); }
if(service === ''){ errors.push('请选择服务类型'); }
if(date === ''){ errors.push('请选择日期'); }
if(time === ''){ errors.push('请选择时间段'); }

if(errors.length > 0){
alert('请检查以下项目：\\n' + errors.join('\\n'));
return;
}

alert('感谢您的预约，我们将在24小时内与您联系！');
});
</script>
</div>
</body>
</html>
